Datetime stamp = Datetime.newInstance(2024, 2, 29, 23, 5, 6);
System.assertEquals(Datetime.newInstance(2025, 2, 28, 23, 5, 6), stamp.addYears(1));
System.assertEquals(29, stamp.dayGmt());
System.assertEquals(60, stamp.dayOfYear());
System.assertEquals(60, stamp.dayOfYearGmt());
System.assertEquals('2/29/2024, 11:05 PM', stamp.format());
System.assertEquals('2024-02-29', stamp.format('yyyy-MM-dd'));
System.assertEquals('2024-03-01 04:35:06', stamp.format('yyyy-MM-dd HH:mm:ss', 'GMT+05:30'));
System.assertEquals('2/29/2024, 11:05 PM', stamp.formatGmt());
System.assertEquals('2024-02-29', stamp.formatGmt('yyyy-MM-dd'));
System.assert(stamp.formatLong().contains('2024'));
System.assert(stamp.getTime() > 0);
System.assertEquals(23, stamp.hourGmt());
System.assert(stamp.isSameDay(Datetime.valueOfGmt('2024-02-29T00:00:01Z')));
Datetime fractional = stamp.addMilliseconds(250);
System.assertEquals(250, fractional.millisecondGmt());
System.assertEquals(5, stamp.minuteGmt());
System.assertEquals(2, stamp.monthGmt());
System.assertEquals(stamp, Datetime.newInstance(stamp.date(), stamp.time()));
System.assertEquals(Datetime.valueOfGmt('2024-02-29T00:00:00Z'), Datetime.newInstance(2024, 2, 29));
System.assertEquals(Datetime.valueOfGmt('1970-01-01T00:00:01Z'), Datetime.newInstance(1000L));
System.assertEquals(stamp, Datetime.newInstanceGmt(stamp.dateGmt(), stamp.timeGmt()));
System.assertEquals(Datetime.valueOfGmt('2024-02-29T00:00:00Z'), Datetime.newInstanceGmt(2024, 2, 29));
System.assertEquals(Datetime.valueOfGmt('2024-02-29T23:05:00Z'), Datetime.parse('2/29/2024, 11:05 PM'));
System.assertEquals(6, stamp.secondGmt());
System.assertEquals(Time.newInstance(23, 5, 6, 0), stamp.time());
Object dtObject = '2024-02-29 23:05:06';
System.assertEquals(stamp, Datetime.valueOf(dtObject));
System.assertEquals(2024, stamp.yearGmt());
Decimal d = Decimal.valueOf('-12.5');
System.assertEquals(12.5, d.abs());
System.assertEquals(6.25, Decimal.valueOf('12.5').divide(Decimal.valueOf('2'), 2));
System.assertEquals(6.3, Decimal.valueOf('12.5').divide(Decimal.valueOf('2'), 1, RoundingMode.HALF_UP));
System.assertEquals(12.5, Decimal.valueOf('12.5').doubleValue());
System.assertEquals(12, Decimal.valueOf('12.5').intValue());
System.assertEquals(12, Decimal.valueOf('12.5').longValue());
System.assertEquals(156.25, Decimal.valueOf('12.5').pow(2));
System.assertEquals(3, Decimal.valueOf('12.5').precision());
System.assertEquals(13, Decimal.valueOf('12.5').round());

